struct Animal {
    virtual void speak() const { std::cout << "...\n"; }
    virtual ~Animal() = default;
};
struct Dog : Animal {
    void speak() const override { std::cout << "Woof\n"; }
};
struct Cat : Animal {
    void speak() const override { std::cout << "Meow\n"; }
};
int main() {
    std::vector<std::unique_ptr<Animal>> zoo;
    zoo.push_back(std::make_unique<Dog>());
    zoo.push_back(std::make_unique<Cat>());
    for (const auto& a : zoo) a->speak();
}

int    add(int a, int b)       { return a + b; }
double add(double a, double b) { return a + b; }

template <typename T>
T biggest(T a, T b) { return a > b ? a : b; }

add(1, 2);          // picks the int version
add(1.5, 2.5);      // picks the double version
biggest(3, 7);      // stamps out biggest<int>
biggest('a', 'z');  // stamps out biggest<char>

void byValue(Animal a)      { a.speak(); }  // copies Animal part
void byRef(const Animal& a) { a.speak(); }  // keeps real type

Dog d;
byValue(d);
byRef(d);
